// Generates typed `as const` ABIs from Foundry artifacts (contracts/out). Run after `forge build`:
//   pnpm --filter @bastion-guardian/contracts run generate
// The generated file is committed so TypeScript builds/CI never need a Solidity toolchain.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, "../../../contracts/out");
const CONTRACTS = [
  "BastionReactiveCore",
  "BastionCallbackRouter",
  "BastionPolicyRegistry",
  "BastionProtectionVault",
  "CrossChainReserveEscrow",
  "RescueSettlementLedger",
  "RescueReceiptRegistry",
  "SolverRegistry",
  "SolverLiquidityVault",
  "SolverQuoteManager",
  "SolverRescueExecutor",
  "FlashRescueExecutor",
  "BastionRiskObserver",
  "BastionEmergencyControl",
  "AaveV3LendingAdapter",
  "FixtureLendingMarket",
  "FixtureOracle",
  "FixtureToken",
  "FixtureSwapVenue",
  "MockReactiveSystem",
  "MockCallbackProxy",
];
const lc = (s) => s[0].toLowerCase() + s.slice(1);
let src =
  "// AUTO-GENERATED by scripts/generate.mjs from contracts/out. Do not edit by hand.\n" +
  "// MockReactiveSystem / MockCallbackProxy are LOCAL SIMULATION stand-ins, never deployed to a public network.\n\n";
for (const name of CONTRACTS) {
  const art = JSON.parse(readFileSync(join(out, `${name}.sol`, `${name}.json`), "utf8"));
  src += `export const ${lc(name)}Abi = ${JSON.stringify(art.abi)} as const;\n\n`;
}
writeFileSync(join(here, "../src/abis.ts"), src);
console.log(`wrote ${CONTRACTS.length} ABIs`);
